(() => {
  'use strict';
  const data=window.OMNIECHO_INVESTIGATION, prior=window.OmniResults, registry=window.OMNIALE_DATA;
  if(!data||!prior||!registry)return;
  const task=data.case, key=task.key;
  task.seq=Math.max(...registry.cases.map(c=>Number(c.seq)||0))+1;
  if(!registry.cases.some(c=>c.key===key))registry.cases.push(task);
  const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const J=v=>E(JSON.stringify(v));
  const N=n=>Number(n).toFixed(4);
  const score=g=>g.score==null?g.v2_score_interval.map(N).join('–'):N(g.score);
  const status=v=>v===true?'通过':v===false?'失败':'待验收';
  const names={direction:'方向',localization3d:'方向与距离',camera_rotation:'相机转动 / 转向关系',motion:'运动方向'};
  const sources={camera:'相机',S1:'报警声',S2:'塑料摩擦声',S3:'钥匙声'};
  const assetMap={"omniecho-investigation/candidate/incident.mp4": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/71d0ddbff4b2c53ead6c-incident.mp4", "omniecho-investigation/case1__sol_01/evidence/E736373124dbb4125.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/c0181c7a75047b7fb3ae-E736373124dbb4125.mkv", "omniecho-investigation/case1__sol_01/evidence/Eaf5286d3f13c40c4.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/2503327a55653b3b0430-Eaf5286d3f13c40c4.mkv", "omniecho-investigation/case1__sol_01/evidence/Ec3554e97ebc548ea.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/92175f1e5d43b238c984-Ec3554e97ebc548ea.mkv", "omniecho-investigation/case1__sol_01/evidence/Ec5b5d7d616aa4a05.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/1c86d29543c6531de714-Ec5b5d7d616aa4a05.mkv", "omniecho-investigation/case1__luna_01/evidence/Ee463ebd1e9274d9f.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/7c4b7d7deeb5a4781af5-Ee463ebd1e9274d9f.mkv", "omniecho-investigation/case1__astra_xhigh_unlimited_20261119_newkey/evidence/E5d3506f851304c41.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/78abef16262a703c499c-E5d3506f851304c41.mkv"}; const asset=p=>assetMap[p]||p;
  const link=(url,label)=>`<a href="${E(asset(url))}" target="_blank" rel="noopener">${E(label)} ↗</a>`;
  const first=data.models[0];
  window.OMNIALE_RESULTS[key]={key,model:first.model,effort:first.effort,total:first.grade.score,verified:first.grade.score,
    accepted:false,gradeStatus:'complete',pendingPoints:0,automatic:null,judge:null,automaticMax:100,judgeMax:0,
    rows:[{maximum:100,points:first.grade.score}],artifacts:first.artifacts,reports:[],seconds:first.seconds,timedOut:false,
    comparisons:data.models.slice(1).map(m=>({model:m.model,total:m.grade.score,verified:m.grade.score})),integrity:{passed:true}};
  let selected=first.key, section='answer';
  function maturity(){return `<h3>任务与评分状态</h3><p>题面与真值已按用户确认完成专家审核。当前仅使用 V2 严格评分：角度误差≤15°、距离误差≤0.5米。本次直接复评原有封存答卷，未改题、未重跑模型。</p><p>真实 Edge 已离线验证三份报告的打开、共51条记录跳转、视频播放及可见字段与JSON一致。按用户要求取消实体扬声器出声评分，R由上述四项均分，三模型均为1。</p><p>四项交付验收均已完成，本页展示最终确定总分。三个模型均未达到F≥0.8的通过门槛，未通过结论已确定。</p><p>G/P由助手在答题会话之外复核，非盲审，非人工专家评分。任务专家审核和本次答卷评分是两件事。</p><p>仍需跨视频扩充题集、校准权重与门槛，以及重复试验。当前是单样本开发结果，三个运行的时间预算不同，不用于泛化能力排名。模型使用本地工具分析四通道音频，并非原生音频输入。</p>`;}
  function answer(m){return `<h3>${E(m.model)} · 冻结调查报告</h3><p>Agent 自行选择分析顺序、抽帧与音频空间分析，调用工具导出证据，生成 HTML 与 JSON，最后验证并封存。三个声源类别和待查字段由题面提供，声源类别识别不计入本轮成绩。</p><div class="oe-links">${link(m.links.report,'打开完整模型报告')}${link(`omniecho-investigation/${m.key}/findings.json`,'结构化答卷')}${link(`omniecho-investigation/${m.key}/evidence_manifest.json`,'证据回执')}</div><p class="oe-note">以下为实际导出的双声道播放预览，仅供浏览；空间分析与证据原件保留四通道。报告中的陈述是模型答卷，不等于原始真值。</p>${m.exports.map((x,i)=>{const base=`omniecho-investigation/${m.key}/`; const preview=x.preview_path;return `<details ${i===0?'open':''}><summary>证据 ${i+1} · ${x.start_s.toFixed(2)}–${x.end_s.toFixed(2)} 秒</summary><video controls playsinline preload="none" src="${asset(base+preview)}" aria-label="${E(m.model)} 证据 ${i+1}"></video><p>${link(base+x.path,'四通道原件')} · ${link(base+preview,'双声道预览')}</p></details>`}).join('')}<p class="oe-note">完整报告在独立页面打开，以保留模型原始布局、锚点和交互。当前页不改写答卷内容。</p>`;}
  function scores(m){const g=m.grade;return `<h3>V2 严格评分 · ${score(g)} / 100</h3><p><b>A = 0.50G + 0.20P + 0.15L + 0.15R；S = 100F(0.50 + 0.50A)</b></p><div class="oe-warning">本版取消单独的实体扬声器出声评分，R总权重不变，由其余四项各分配25%。四项均通过，R=1。三模型均因 F&lt;0.8 未通过。</div><table><thead><tr><th>评分项</th><th>本模型</th><th>依据</th></tr></thead><tbody><tr><td>F 事实正确率</td><td>${g.strict_fact_correct}/18 · ${N(g.F)}</td><td>方向精确匹配；角度误差≤15°、距离误差≤0.5米，边界包含</td></tr><tr><td>G 证据支持</td><td>${N(g.G)}</td><td>18项均值；充分支持1，相关但关键歧义未解决0.5，只有断言0</td></tr><tr><td>P 行动效果</td><td>${N(g.P)}</td><td>${E(m.review.process.reason)}</td></tr><tr><td>L 证据定位</td><td>${N(g.L)}</td><td>${m.review.navigation.records.filter(r=>r.localized_navigation).length}/17 条符合范围与覆盖要求</td></tr><tr><td>R 浏览器交付</td><td>${N(g.R)}</td><td>离线打开、17条定位、视频播放、页面与JSON一致四项均通过</td></tr></tbody></table><p>通过需 S≥80、F≥0.8、G≥0.8、R=1，并满足封存与来源完整性要求。当前均未通过。</p><table><thead><tr><th>事实类别</th><th>正确 / 总数</th></tr></thead><tbody>${Object.entries(g.breakdown).map(([k,v])=>`<tr><td>${names[k]}</td><td>${v.correct}/${v.total}</td></tr>`).join('')}</tbody></table><h3>18 个事实：真值、作答与证据支持</h3><div class="oe-scroll"><table class="oe-facts"><thead><tr><th>事实 / 记录</th><th>对象 · 时段 · 坐标</th><th>类别</th><th>原标注参考</th><th>模型答案 / 误差</th><th>事实判定</th><th>证据支持 G</th></tr></thead><tbody>${g.facts.map(a=>{const r=data.coverage.records.find(r=>r.record_id===a.record_id),v=m.review.atoms.find(x=>x.atom_id===a.atom_id);return `<tr><td>${a.atom_id}/${a.record_id}</td><td>${sources[r.source_id]}<small>${r.time_s??r.interval_s?.join('–')} 秒 · ${E(r.coordinate_frame)}</small></td><td>${names[a.category]}</td><td><code>${J(a.reference)}</code></td><td><code>${J(a.prediction)}</code><small>误差：${J(a.errors)}</small></td><td class="${a.new_correct?'oe-pass':'oe-fail'}">${a.new_correct?'正确':'错误'}</td><td>${v.support}<small>${E(v.reason)}</small></td></tr>`}).join('')}</tbody></table></div><h3>17 条证据定位 L</h3><p>定位覆盖所需时段，且范围≤max(3秒,所需时段+2秒)才得分。能跳到记录与证据定位足够精确分别检查。</p><div class="oe-scroll"><table><thead><tr><th>记录</th><th>定位通过</th><th>需要的原始时段</th><th>实际导航范围</th></tr></thead><tbody>${m.review.navigation.records.map(r=>`<tr><td>${r.record_id}</td><td>${r.localized_navigation?'是':'否'}</td><td>${r.required_span.join('–')}</td><td>${r.candidates.map(x=>x.original_span.join('–')).join(' / ')||'未找到'}</td></tr>`).join('')}</tbody></table></div><p>${link(m.links.grade,'V2评分 JSON')} · ${link(m.links.review,'逐项复核记录')}</p>`;}
  function records(m){return `<h3>运行与来源</h3><p>${E(m.model)} / xhigh；${E(m.timeBudget||'35 分钟上限')}，实际 ${(m.seconds/60).toFixed(2)} 分钟。单次尝试，${m.apiCalls} 次 API 调用，${m.apiErrors} 次 API 错误。模型通过本地 Python、FFmpeg 和图像工具处理音视频，没有原生音频输入。</p><p>WSL + bubblewrap 隔离，输入只读、公网关闭、隐藏真值与其他答卷不可见。宿主代理调用模型服务，接口返回模型名与请求一致；第三方网关背后的模型权重未独立认证。</p><div class="oe-links">${Object.entries({run:'运行原始记录',trace:'宿主工具轨迹',review:'V2逐项复核记录',grade:'评分 JSON',final:'最终回复'}).map(([k,v])=>link(m.links[k],v)).join('')}</div><h3>素材和真值从哪里来</h3><p>${link('https://huggingface.co/datasets/PKU-VaLuE-Lab/OmniEchoBench','OmniEchoBench 数据集')} 中的 <code>OmniEchoBench-QA/videos/vid_0095.mp4</code>（S1107），37.333333 秒、1920×1080、48kHz 四通道。使用原视频与原 QA 答案，没有合成新的声音事件。</p><p>数据版本 <code>5c85a02fd612f22c26c62f2fad883a46c4685213</code>。原 QA 零基索引 89–108 中，排除结束于 37.5 秒、超过实测片长的 106 与 108；剩余 18 个事实。由完整原答案解析真值，保留原真值，评分使用本页 V2 严格容差。调查流程、证据回执与报告交付是我们新增的 agent 包装。</p><p class="oe-note">因直连下载不稳定，实际使用 HF 镜像；原媒体 SHA256 与冻结 LFS 清单匹配，并已完整解码。原媒体 SHA256：<code>71d0ddbff4b2c53ead6c93c52f2da8a68d9d628fadfd191402b7d7780b3068fd</code>。这能确认文件来源和完整性，不能替代标注正确性复核。上游 README 声明 CC BY-NC-SA 4.0。</p><div class="oe-links">${link('https://arxiv.org/html/2609.23407v2','论文')}${link('https://github.com/PKU-VaLuE-Lab/OmniEcho/tree/1f3696d637027edc673db81629aed1586e4c1983','上游代码')}${link('omniecho-investigation/asset_provenance.json','素材来源与哈希')}${link('omniecho-investigation/candidate/SCORING.md','当前V2评分规则')}</div><h3>全部冻结交付物</h3><div class="oe-scroll"><table><thead><tr><th>文件</th><th>大小</th><th>查看</th></tr></thead><tbody>${m.artifacts.map(f=>`<tr><td>${E(f.name)}</td><td>${(f.bytes/1e6).toFixed(2)} MB</td><td>${link(f.url,'打开 / 下载')}</td></tr>`).join('')}</tbody></table></div>`;}
  function acceptance(m){return `<h3>真实浏览器交付验收</h3><p>${E(data.browserEnvironment)}</p><table><thead><tr><th>检查项</th><th>结果</th></tr></thead><tbody>${Object.entries({offline_open:'离线打开',all_record_navigation:'17条记录跳转',video_playback:'视频播放',visible_json_consistency:'可见字段与JSON一致'}).map(([k,v])=>`<tr><td>${v}</td><td>${status(m.browser[k])}</td></tr>`).join('')}</tbody></table><p>视频已验证播放时钟推进和真实画面尺寸。媒体音轨与解码由完整性检查覆盖，不单独评分实体扬声器出声。原报告未修改；Luna 的视频通过报告内 MP4 链接验证。</p><p>${link(m.links.browser,'浏览器播放截图')} · ${link('omniecho-investigation/browser_acceptance.json','全部验收记录')}</p>`;}
  function render(c,r,target){
    if(c.key!==key)return prior.render(c,r,target);
    const m=data.models.find(m=>m.key===selected);
    target.querySelectorAll('video,audio').forEach(el=>el.pause());
    target.innerHTML=`<section class="oe" data-omniecho><div class="oe-top"><h2>多声源调查 · ${data.models.length} 组结果</h2><span class="oe-chip">开发试跑 / 单个原视频</span></div><p>同题、同输入、原封存答卷；按用户要求统一复评为 V2 严格版，未重跑。均为 xhigh，时间预算见各行。交付验收完成，展示最终确定总分。</p><div class="oe-scroll"><table data-oe-models><thead><tr><th>模型</th><th>事实正确</th><th>G / P / L / R</th><th>得分 / 100</th><th>实际用时</th><th>状态 / 答卷</th></tr></thead><tbody>${data.models.map(x=>`<tr class="${m.key===x.key?'oe-selected':''}"><td>${x.model}<small>xhigh · ${E(x.timeBudget||'35 分钟上限')}</small></td><td>${x.grade.strict_fact_correct} / 18</td><td>${N(x.grade.G)} / ${N(x.grade.P)} / ${N(x.grade.L)}<small>R ${N(x.grade.R)}</small></td><td><b>${score(x.grade)}</b></td><td>${(x.seconds/60).toFixed(2)} 分钟</td><td><span class="${x.grade.task_pass?'oe-pass':'oe-fail'}">${x.grade.task_pass?'通过':'未通过'}</span><br><button class="button" data-oe-model="${x.key}" aria-pressed="${x.key===m.key}">${x.key===m.key?'正在查看':'查看答卷'}</button></td></tr>`).join('')}</tbody></table></div><div class="oe-tabs" role="tablist" aria-label="调查结果分区">${[['answer','答卷与证据'],['scores','评分明细'],['records','交付与来源'],['maturity','浏览器验收与成熟度']].map(([k,v])=>`<button id="oe-tab-${k}" role="tab" aria-controls="oe-content" tabindex="${k===section?0:-1}" aria-selected="${k===section}" data-oe-section="${k}">${v}</button>`).join('')}</div><div id="oe-content" role="tabpanel" aria-labelledby="oe-tab-${section}">${section==='answer'?answer(m):section==='scores'?scores(m):section==='records'?records(m):acceptance(m)+maturity()}</div></section>`;
    target.querySelectorAll('[data-oe-model]').forEach(b=>b.onclick=()=>{selected=b.dataset.oeModel;render(c,r,target);target.querySelector(`[data-oe-model="${selected}"]`).focus({preventScroll:true});});
    const keys=['answer','scores','records','maturity'];
    target.querySelectorAll('[data-oe-section]').forEach(b=>{const go=s=>{section=s;render(c,r,target);target.querySelector(`#oe-tab-${section}`).focus({preventScroll:true});};b.onclick=()=>go(b.dataset.oeSection);b.onkeydown=e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();go(keys[e.key==='Home'?0:e.key==='End'?3:(keys.indexOf(section)+(e.key==='ArrowRight'?1:3))%4]);};});
    target.querySelectorAll('video,audio').forEach(el=>el.addEventListener('play',()=>target.querySelectorAll('video,audio').forEach(o=>{if(o!==el)o.pause();})));
  }
  window.OmniResults=Object.freeze({...prior,render,overview(cases,results,target){prior.overview(cases,results,target);const row=target.querySelector(`a[href="#${key}/results"]`)?.closest('tr');if(row){row.classList.add('oe-overview');row.innerHTML=`<td><a href="#${key}/results"><b>多声源事件调查与证据报告</b><small>开发试跑 · ${data.models.length} 组 · 单样本</small></a></td><td colspan="4">${data.models.map(m=>`${m.model} · <b>${score(m.grade)}</b> / 100 · ${m.grade.strict_fact_correct}/18 个事实`).join('<br>')}</td><td>${data.models.filter(m=>m.grade.task_pass).length} 组通过<br>V2严格版 · 评分完成</td><td><a class="button" href="#${key}/results">查看 ↗</a></td>`;}}});
})();
